INSERT INTO RDF_META_COMMON(
	VCARD_FN, VCARD_HASEMAIL, VCARD_HASTELEPHONE, FOAF_NAME, FOAF_HOMEPAGE, FOAF_MBOX, FOAF_PHONE, DCT_LICENSE, DCT_RIGHTS, REG_ID, UPDT_ID)
	VALUES (
			#{vcardFn}
			,#{vcardHasemail}
			,#{vcardHastelephone}
			,#{foafName}
			,#{foafHomepage}
			,#{foafMbox}
			,#{foafPhone}
			,#{dctLicense}
			,#{dctRights}
			,'ADMIN'
			, 'ADMIN');

INSERT INTO RDF_META_DATASET(
	JOB_ID, DCT_TITLE, DCT_ACCESSRIGHTS, DCT_DESCRIPTION, DCT_IDENTIFIER, DCAT_THEME, DCAT_KEYWORD, PRICEINFO, DCAT_LANDINGPAGE, REG_ID, UPDT_ID)
VALUES (
		cast (#{jobId}as integer) 
		,#{dctTitle}
		,#{dctAccessrights}
		,#{dctDescription}
		,#{dctIdentifier}
		,#{dcatTheme}
		,#{dcatKeyword}
		,#{priceinfo}
		,'-'
		,'ADMIN'
		,'ADMIN');

