UPDATE JOB_MST SET
	JOB_NM_KR= #{frmJobNmKr}
	,CRON_EXE_CYCLE= #{frmCronExeCycle}
	,USE_AT = #{frmUseAt}
WHERE JOB_ID = #{jobId}::Integer

UPDATE JOB_LINK_CONFIG SET
	SEND_FILE_SAVE_DIR= #{frmSendSaveDir}

		,JOB_TYPE=#{frmJobType}


		,UDT_API_END_POINT=#{frmUdtApiEndPoint}


		,UDT_API_PARAM=#{frmUdtApiParam}

WHERE JOB_ID = #{jobId}::Integer

