INSERT INTO JOB_MST(
	JOB_NM_EN, JOB_NM_KR, CLASS_NM, METHOD_NM, CRON_EXE_CYCLE, JOB_DESC, SAVE_TB_NM, RECIVE_INST, RECIVE_SYS, REG_ID, UPDT_ID
)
VALUES(
	UPPER(#{saveTbNm})
	,#{jobNmKr}
	,#{classNm}
	,'execute'
	,#{cronExeCycle}
	,#{jobNmKr}
	,UPPER(#{saveTbNm})
	,''
	,''
	,#{userId}
	,#{userId}
)

	SELECT 
		JOB_ID
	FROM
		JOB_MST
	WHERE SAVE_TB_NM = UPPER(#{saveTbNm})

INSERT INTO JOB_LINK_CONFIG(
	JOB_ID, JOB_TYPE, UDT_API_END_POINT, UDT_API_RSLT_TYPE, UDT_API_PARAM, UDT_API_FIELD_LIST, SEND_FILE_SAVE_DIR
)
VALUES(
	#{jobId}
	, UPPER(#{jobReqTyp})
	, #{apiUrl}
	, UPPER(#{udtApiRsltType})
	, #{apiOptionParam}
	, #{selectField}
	, ''
)

INSERT INTO JOB_PROCESS_SN(
	JOB_ID, PROCESS_SN, PROCESS_ID
)
VALUES(
	#{jobId}
	, #{processSn}
	, #{processId}
)

